package com.beeboee.magnot.client;
import com.beeboee.magnot.Magnot;import com.beeboee.magnot.item.FerrousTubeItem;import com.beeboee.magnot.network.MagnotNetwork;import com.beeboee.magnot.region.FerrousRegion;import com.beeboee.magnot.registry.MagnotItems;import com.mojang.blaze3d.vertex.*;import com.mojang.math.Matrix3f;import com.mojang.math.Matrix4f;import net.minecraft.client.Minecraft;import net.minecraft.client.player.LocalPlayer;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.texture.OverlayTexture;import net.minecraft.core.BlockPos;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.*;import net.minecraftforge.api.distmarker.Dist;import net.minecraftforge.client.event.*;import net.minecraftforge.event.TickEvent;import net.minecraftforge.eventbus.api.SubscribeEvent;import net.minecraftforge.fml.common.Mod;import java.util.*;
@Mod.EventBusSubscriber(modid=Magnot.MOD_ID,value=Dist.CLIENT,bus=Mod.EventBusSubscriber.Bus.FORGE)public final class MagnotClientEvents{private static final ResourceLocation TEX=new ResourceLocation(Magnot.MOD_ID,"textures/special/ferrous_region.png");private static final Map<Object,State> states=new LinkedHashMap<>();private static final Object PREVIEW=new Object();private static long last,next;private static final int RED=0xBD2537,YELLOW=0xFFD43B;private MagnotClientEvents(){}@SubscribeEvent public static void tick(TickEvent.ClientTickEvent e){if(e.phase!=TickEvent.Phase.END)return;for(State s:states.values())s.fresh=false;Minecraft mc=Minecraft.getInstance();LocalPlayer p=mc.player;if(p==null||mc.level==null||!p.getMainHandItem().is(MagnotItems.FERROUS_TUBE.get()))return;Optional<FerrousRegion> selected=selected(p);for(FerrousRegion r:ClientFerrousRegionStore.regions()){if(r.bounds().distanceToSqr(p.position())>625)continue;boolean active=selected.map(FerrousRegion::id).filter(r.id()::equals).isPresent();show(r.id(),r.bounds(),RED,active);}Optional<BlockPos> first=FerrousTubeItem.getFirstCorner(p.getMainHandItem());if(first.isPresent()&&mc.hitResult instanceof BlockHitResult hit&&hit.getType()==HitResult.Type.BLOCK){BlockPos raw=hit.getBlockPos(),end=FerrousTubeItem.clampToRegionLimit(first.get(),raw);int color=FerrousTubeItem.exceedsRegionLimit(first.get(),raw)?YELLOW:RED;p.displayClientMessage(Component.translatable("message.magnot.click_to_confirm").withStyle(s->s.withColor(color)),true);show(PREVIEW,FerrousRegion.fromCorners(UUID.randomUUID(),first.get(),end).bounds(),color,true);}}@SubscribeEvent public static void click(InputEvent.InteractionKeyMappingTriggered e){if(!e.isAttack())return;Minecraft mc=Minecraft.getInstance();LocalPlayer p=mc.player;if(p==null||mc.level==null||!p.getMainHandItem().is(MagnotItems.FERROUS_TUBE.get()))return;e.setCanceled(true);e.setSwingHand(true);if(mc.level.getGameTime()>=next){next=mc.level.getGameTime()+5;selected(p).ifPresent(r->MagnotNetwork.remove(r.id()));}}@SubscribeEvent public static void logout(ClientPlayerNetworkEvent.LoggingOut e){ClientFerrousRegionStore.clear();states.clear();}@SubscribeEvent public static void render(RenderLevelStageEvent e){if(e.getStage()!=RenderLevelStageEvent.Stage.AFTER_TRANSLUCENT_BLOCKS||states.isEmpty())return;long now=System.nanoTime();float dt=last==0?0:Math.min((now-last)/1_000_000_000f,.1f);last=now;Vec3 cam=e.getCamera().getPosition();PoseStack pose=e.getPoseStack();MultiBufferSource.BufferSource buffers=Minecraft.getInstance().renderBuffers().bufferSource();Iterator<State> it=states.values().iterator();while(it.hasNext()){State s=it.next();if(!s.active)s.strength=Math.max(0,s.strength-dt/.18f);if(!s.fresh&&s.strength<=.001){it.remove();continue;}draw(pose,buffers,s,cam);}buffers.endBatch();}private static Optional<FerrousRegion> selected(LocalPlayer p){Vec3 a=p.getEyePosition();return ClientFerrousRegionStore.selected(a,a.add(p.getLookAngle().scale(6)));}private static void show(Object id,AABB b,int color,boolean active){State s=states.computeIfAbsent(id,q->new State());s.box=b;s.color=color;s.active=active;s.fresh=true;if(active)s.strength=1;}private static void draw(PoseStack pose,MultiBufferSource.BufferSource buffers,State s,Vec3 cam){float q=s.strength;VertexConsumer lines=buffers.getBuffer(RenderType.lines());Matrix4f m=pose.last().pose();Matrix3f n=pose.last().normal();AABB b=s.box.move(-cam.x,-cam.y,-cam.z);LevelRenderer.renderLineBox(pose,lines,b,(s.color>>16&255)/255f,(s.color>>8&255)/255f,(s.color&255)/255f,1);if(q<=.001)return;VertexConsumer c=buffers.getBuffer(RenderType.entityTranslucent(TEX));int a=Math.max(1,Math.round(72*q));double x0=b.minX-1.0/128,x1=b.maxX+1.0/128,y0=b.minY-1.0/128,y1=b.maxY+1.0/128,z0=b.minZ-1.0/128,z1=b.maxZ+1.0/128;face(c,m,n,x0,y0,z0,x1,y0,z1,s,a,0,-1,0);face(c,m,n,x0,y1,z0,x1,y1,z1,s,a,0,1,0);face(c,m,n,x0,y0,z0,x0,y1,z1,s,a,-1,0,0);face(c,m,n,x1,y0,z0,x1,y1,z1,s,a,1,0,0);face(c,m,n,x0,y0,z0,x1,y1,z0,s,a,0,0,-1);face(c,m,n,x0,y0,z1,x1,y1,z1,s,a,0,0,1);}private static void face(VertexConsumer c,Matrix4f m,Matrix3f n,double x0,double y0,double z0,double x1,double y1,double z1,State s,int a,float nx,float ny,float nz){v(c,m,n,x0,y0,z0,0,0,s,a,nx,ny,nz);v(c,m,n,x1,y0,z1,1,0,s,a,nx,ny,nz);v(c,m,n,x1,y1,z1,1,1,s,a,nx,ny,nz);v(c,m,n,x0,y1,z0,0,1,s,a,nx,ny,nz);}private static void v(VertexConsumer c,Matrix4f m,Matrix3f n,double x,double y,double z,float u,float v,State s,int a,float nx,float ny,float nz){c.vertex(m,(float)x,(float)y,(float)z).color(s.color>>16&255,s.color>>8&255,s.color&255,a).uv(u,v).overlayCoords(OverlayTexture.NO_OVERLAY).uv2(LightTexture.FULL_BRIGHT).normal(n,nx,ny,nz).endVertex();}private static final class State{AABB box;int color;boolean active,fresh;float strength;}}
